/bin/zsh -lc "./run_python smoke.py && ./run_python - <<'PY'
import math
import tempfile
from app import Queue

with tempfile.TemporaryDirectory() as d:
    path = d + '/q.db'
    q1, q2 = Queue(path), Queue(path)
    source = {'nested': [1, None, {'ok': True}]}
    q1.put('job', source)
    source['nested'].append('late')
    first = q1.claim('worker', 10, 2)
    assert first == {'payload': {'nested': [1, None, {'ok': True}]}, 'expires_at': 12, 'receipt': {'job_id': 'job', 'worker': 'worker', 'generation': 1}}
    first['payload']['nested'].clear()
    assert q2.claim('worker', 11.999, 1) is None
    second = q2.claim('worker', 12, 3)
    assert second['payload'] == {'nested': [1, None, {'ok': True}]}
    assert q1.ack(first['receipt'], 12) is False
    assert q1.ack(second['receipt'], 12) is True
    assert q2.ack(second['receipt'], 12) is False
    assert Queue(path).claim('other', 13, 1) is None
    try:
        q1.put('job', 'duplicate')
    except ValueError:
        pass
    else:
        raise AssertionError('completed ID was reusable')

with tempfile.TemporaryDirectory() as d:
    q = Queue(d + '/q.db')
    q.put('one', 'kept')
    for invalid in (True, False, 0, -1, math.inf, -math.inf, math.nan):
        try:
            q.claim('worker', 0, invalid)
        except ValueError:
            pass
        else:
            raise AssertionError(f'accepted invalid lease: {invalid"'!r}'"')
    assert q.claim('worker', 0, 1)['payload'] == 'kept'

with tempfile.TemporaryDirectory() as d:
    q = Queue(d + '/q.db')
    cyclic = []
    cyclic.append(cyclic)
    try:
        q.put('bad', cyclic)
    except (TypeError, ValueError, RecursionError):
        pass
    else:
        raise AssertionError('accepted cyclic payload')
    deep = 0
    for _ in range(1100):
        deep = [deep]
    try:
        q.put('deep', deep)
    except (TypeError, ValueError, RecursionError):
        pass
    else:
        raise AssertionError('accepted payload beyond JSON nesting depth')
    q.put('good', {'ok': 1})
    assert q.claim('w', 0, 1)['payload'] == {'ok': 1}
print('targeted contract checks passed')
PY"

